def sequential_model(data, scripted_model):
    model = nn.Sequential(nn.Linear(4, 3), nn.ReLU(), nn.Linear(3, 1),)
    if scripted_model:
        model = torch.jit.script(model)

    train_model(model=model, data=data)
    return model

