def lint(request):
    lintargs = getattr(request.module, 'lintargs', {})
    return LintRoller(root=here, **lintargs)

def files(filedir, request):
    suffix_filter = getattr(request.module, 'files', [''])
    return [os.path.join(filedir, p) for p in os.listdir(filedir)
            if any(p.endswith(suffix) for suffix in suffix_filter)]

def linters(lintdir, request):
    suffix_filter = getattr(request.module, 'linters', ['.lint.py'])
    return [os.path.join(lintdir, p) for p in os.listdir(lintdir)
            if any(p.endswith(suffix) for suffix in suffix_filter)]

def run(parser, lintdir, files):
    if lintdir not in cli.SEARCH_PATHS:
        cli.SEARCH_PATHS.append(lintdir)

    def inner(args=None):
        args = args or []
        args.extend(files)
        lintargs = vars(parser.parse_args(args))
        lintargs['root'] = here
        return cli.run(**lintargs)
    return inner

def parse(lintdir):
    parser = Parser()

    def _parse(name):
        path = os.path.join(lintdir, name)
        return parser(path)
    return _parse

def path(filedir):
    def _path(name):
        return os.path.join(filedir, name)
    return _path

